import { Component } from '@angular/core';
import { CreditoProductoFinancieroDocumentoService } from '../../../../controllers/credito.producto.financiero.documento.service';
import { CreditoService } from '../../../../controllers/credito.service';
import { TablaComponent, TableDefinition } from "../../../../shared/tabla/tabla.component";
import { FormularioFlotanteComponent } from '../../../../shared/formulario-flotante/formulario-flotante.component';
import { NuevoDocumentoCreditoComponent } from "../nuevo-documento-credito/nuevo-documento-credito.component";
import { Button } from '../../../../shared/button/button.component';
import { Credito } from '../../../../models/credito.model';
import { ActivatedRoute } from '@angular/router';
import { UtilsService } from '../../../../services/utils.service';


const TABLA_DEF:TableDefinition={
  columns:[
    {
      key:'productos_financieros_documentos',
      keyList:['productos_financieros_documentos','documento','nombre'],
      header:'Documento',
    },
    {
      key:'productos_financieros_documentos',
      subKey:'prioridad',
      header:'Prioridad'
    },
    {
      key:'autorizado_por_usuario',
      subKey:'nombre',
      header:'Autorizado Por',
    },
    {
      key:'autorizado_fecha',
      header:'Autorizado Fecha',
      pipe:'date'
    },
  ]
}

const EDIT_BUTTON:Button={
  style:{
    icon:'bi bi-file-earmark-arrow-up-fill',
    button:'btn btn-sm btn-primary'
  }
}

@Component({
    selector: 'app-list-documentos-creditos',
    imports: [
        TablaComponent,
        FormularioFlotanteComponent,
        NuevoDocumentoCreditoComponent
    ],
    templateUrl: './list-documentos-creditos.component.html',
    styleUrl: './list-documentos-creditos.component.css'
})
export class ListDocumentosCreditosComponent {
  tabla=TABLA_DEF
  editButton= EDIT_BUTTON
  showAdd:boolean=false
  credito?:Credito

  constructor(
    public creditoDocumentoController: CreditoProductoFinancieroDocumentoService,
    private creditoController:CreditoService,
    private route: ActivatedRoute,
    private utils: UtilsService,
  ){}

  ngOnInit(){
    this.route.parent?.paramMap.subscribe(async (params)=>{
      const credito_id= this.utils.intOrNull(params.get('credito_id'))
      if(credito_id){
        this.credito= await this.creditoController.find(credito_id)
      }
    })
  }
}
