import { Component } from '@angular/core';
import { CreditoProductoFinancieroDocumentoService } from '../../../../controllers/credito.producto.financiero.documento.service';
import { Form } from '../../../../shared/generic-form/generic-form.component';
import { CreditoProductoFinancieroDocumento } from '../../../../models/creditos.productos.financieros.documento';
import { Credito } from '../../../../models/credito.model';
import { CreditoService } from '../../../../controllers/credito.service';
import { UtilsService } from '../../../../services/utils.service';
import { ActivatedRoute } from '@angular/router';
import { ProductoFinancieroDocumento } from '../../../../models/producto.financiero.documento.model';
import { ProductoFinancieroDocumentoService } from '../../../../controllers/producto.financiero.documento';
import { FormsModule } from '@angular/forms';


@Component({
    selector: 'app-nuevo-documento-credito',
    imports: [
    FormsModule
],
    templateUrl: './nuevo-documento-credito.component.html',
    styleUrl: './nuevo-documento-credito.component.css'
})
export class NuevoDocumentoCreditoComponent {
  credito?:Credito
  productoFinancieroDocumentos: ProductoFinancieroDocumento[]=[]
  documentoSelected:number=0;
  form:Partial<CreditoProductoFinancieroDocumento>={}
  constructor(
    private utils:UtilsService,
    private route: ActivatedRoute,
    public creditoDocumentoController:CreditoProductoFinancieroDocumentoService,
    private productoFinancieroDocumentoController: ProductoFinancieroDocumentoService,
    private creditoController:CreditoService
  ){}

  ngOnInit(){
    this.route.parent?.paramMap.subscribe(async (params)=>{
      const id= this.utils.intOrNull(params.get('credito_id'))
      if(id){
        this.credito= await this.creditoController.find(id)
        this.setDocumentos()
      }
    })
  }

  async setDocumentos(){
    this.productoFinancieroDocumentos= (await this.productoFinancieroDocumentoController.get({
      productos_financiero_id:this.credito?.productos_financiero_id
    },undefined,['documento'])).data??[]
  }

  nuevoDocumento(){
    this.creditoDocumentoController.new({
      credito_id:this.credito?.id,
      productos_financieros_documento_id:this.documentoSelected
    })
  }
}
