import { Component } from '@angular/core';
import { CreditoProductoFinancieroDocumento } from '../../../../models/creditos.productos.financieros.documento';
import { UtilsService } from '../../../../services/utils.service';
import { CreditoProductoFinancieroDocumentoService } from '../../../../controllers/credito.producto.financiero.documento.service';
import { ActivatedRoute } from '@angular/router';
import { CommonModule, DatePipe } from '@angular/common';
import { FileInputComponent } from "../../../../shared/file-input/file-input.component";

@Component({
    selector: 'app-form-documentos-creditos',
    imports: [
        CommonModule,
        DatePipe,
        FileInputComponent
    ],
    templateUrl: './form-documentos-creditos.component.html',
    styleUrl: './form-documentos-creditos.component.css'
})
export class FormDocumentosCreditosComponent {
  creditoDocumento?:CreditoProductoFinancieroDocumento
  file:any
  cliente:string=''

  constructor(
    public utils: UtilsService,
    private route: ActivatedRoute,

    public creditoDocumentoController: CreditoProductoFinancieroDocumentoService,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const documento_id= this.utils.intOrNull(params.get('documento_id'))
      if(documento_id){
        await this.setCredito(documento_id)
        this.setNombreCliente()
      }
    })
  }

  async setCredito(documento_id:number){
    this.creditoDocumento= await this.creditoDocumentoController.find(documento_id,['credito','productosFinancierosDocumentos.documento','credito.datosPersonaFisica','credito.datosPersonasMorales','usuarios','autorizadoPorUsuario'])
  }

  async aprobarDocumento(){
    const res =await this.creditoDocumentoController.verificarDocumento(this.creditoDocumento!.id)
    console.log(res)
    if(res.status){
      this.setCredito(this.creditoDocumento!.id)
    }
  }

  setNombreCliente(){
    if(this.creditoDocumento?.credito?.datos_persona_fisica){
      this.cliente= this.creditoDocumento.credito.datos_persona_fisica.datos_personales?.nombre??''
    }else{
      this.cliente= this.creditoDocumento?.credito?.datos_personas_morales?.razon_social??''
    }
  }
}
